import { playersMatching } from "../persistence/mutation-scope.js";
/**
 * Auction service — escrow, round lifecycle, enter/bid/window.
 * Call bindAuctionApi(deps) once from server.js after helpers exist.
 */
import {
  AUCTION_HALLS,
  auctionEntryFee,
  auctionHallForId,
  auctionWindowFee,
  enterAuctionRound,
  upsertBid,
  aiBidsForRough,
  settleAuctionRound,
  buildAuctionSettleModalEvent
} from "../../shared/domain/auction/jade-auction.js";
import {
  grantPlayerExp,
  playerLevelForExp
} from "../../shared/domain/progression/player-progression.js";
import { settlePlayerAchievements } from "./achievement-rewards.js";
import { attemptAtomicMutation } from "./atomic-mutation.js";
import { auctionRoundsForState, auctionRoundForHall, storeAuctionRound } from "./auction-rounds.js";

let api = null;

export const AUCTION_HALL_LOT_PROFILES = Object.freeze({
  novice: Object.freeze({
    mass: Object.freeze([0.7, 2.2]),
    weights: Object.freeze([0.38, 0.30, 0.18, 0.09, 0.04, 0.01])
  }),
  regular: Object.freeze({
    mass: Object.freeze([0.9, 2.8]),
    weights: Object.freeze([0.24, 0.30, 0.24, 0.14, 0.065, 0.015])
  }),
  premium: Object.freeze({
    mass: Object.freeze([1.1, 3.3]),
    weights: Object.freeze([0, 0.18, 0.32, 0.28, 0.16, 0.06])
  }),
  special: Object.freeze({
    mass: Object.freeze([1.8, 3.5]),
    weights: Object.freeze([0, 0.10, 0.25, 0.30, 0.23, 0.12])
  }),
  legendary: Object.freeze({
    mass: Object.freeze([1.4, 3.5]),
    weights: Object.freeze([0, 0, 0.12, 0.32, 0.34, 0.22])
  })
});

const AUCTION_QUALITY_KEYS = Object.freeze(["bean", "glutinous", "stickyIce", "ice", "highIce", "glass"]);

function auctionQualityKeyForRoll(profile, roll) {
  const value = Math.max(0, Math.min(0.999999, Number(roll) || 0));
  let cursor = 0;
  for (let index = 0; index < AUCTION_QUALITY_KEYS.length; index += 1) {
    cursor += Number(profile.weights[index] || 0);
    if (value < cursor) return AUCTION_QUALITY_KEYS[index];
  }
  return AUCTION_QUALITY_KEYS[AUCTION_QUALITY_KEYS.length - 1];
}

export function createAuctionHallRoughs(hallId, makeRoughStone, count = 8, rng = Math.random) {
  if (typeof makeRoughStone !== "function") return [];
  const id = AUCTION_HALL_LOT_PROFILES[hallId] ? hallId : "novice";
  const profile = AUCTION_HALL_LOT_PROFILES[id];
  const total = Math.max(1, Math.round(Number(count) || 8));
  return Array.from({ length: total }, () => {
    const qualityKey = auctionQualityKeyForRoll(profile, rng());
    const [minMass, maxMass] = profile.mass;
    const mass = Math.round((minMass + rng() * (maxMass - minMass)) * 10) / 10;
    return {
      ...makeRoughStone({ qualityKey, mass, rng }),
      sourceHallId: id
    };
  });
}

export function bindAuctionApi(nextApi) {
  api = nextApi;
}

function requireApi() {
  if (!api) throw new Error("auction-service: bindAuctionApi() was not called");
  return api;
}

export function normalizeAuctionEscrow(player) {
  const { money } = requireApi();
  if (!player) return [];
  if (!Array.isArray(player.auctionEscrow)) player.auctionEscrow = [];
  player.auctionEscrow = player.auctionEscrow
    .filter((entry) => entry && entry.roughId)
    .map((entry) => ({
      roughId: String(entry.roughId),
      roundId: String(entry.roundId || ""),
      amount: money(entry.amount),
      at: Number(entry.at || 0)
    }))
    .filter((entry) => entry.amount > 0);
  return player.auctionEscrow;
}

export function auctionEscrowForRough(player, roughId) {
  const id = String(roughId || "");
  return normalizeAuctionEscrow(player).find((entry) => entry.roughId === id) || null;
}

export function setAuctionEscrow(player, { roughId, roundId, amount, at }) {
  const { money } = requireApi();
  normalizeAuctionEscrow(player);
  const id = String(roughId || "");
  if (!id) return null;
  const nextAmount = money(amount);
  const index = player.auctionEscrow.findIndex((entry) => entry.roughId === id);
  if (nextAmount <= 0) {
    if (index >= 0) player.auctionEscrow.splice(index, 1);
    return null;
  }
  const entry = {
    roughId: id,
    roundId: String(roundId || ""),
    amount: nextAmount,
    at: Number(at || Date.now())
  };
  if (index >= 0) player.auctionEscrow[index] = entry;
  else player.auctionEscrow.push(entry);
  return entry;
}

/** 按差额冻—退还暗标抵押；cash 始终表示可用现金 */
export function applyAuctionBidEscrow(player, rough, nextAmount, round, now = Date.now()) {
  const { money, holdDeposit, releaseDeposit } = requireApi();
  const prev = auctionEscrowForRough(player, rough.id);
  const previousAmount = money(prev?.amount || 0);
  const target = money(nextAmount);
  const delta = target - previousAmount;
  if (delta > 0) {
    if (!holdDeposit(player, delta, `公盘抵押${rough.name}`, {
      source: "auctionEscrow",
      itemId: rough.id,
      repEligible: false
    })) {
      return { ok: false, message: `可用现金不足，还需 ${delta}。` };
    }
  } else if (delta < 0) {
    releaseDeposit(player, Math.abs(delta), `公盘退还抵押：${rough.name}`, {
      source: "auctionEscrowRefund",
      itemId: rough.id,
      repEligible: false
    });
  }
  setAuctionEscrow(player, {
    roughId: rough.id,
    roundId: round?.id,
    amount: target,
    at: now
  });
  return { ok: true, escrowed: target, delta, previousAmount };
}

export function consumeAuctionEscrow(player, roughId) {
  const { money } = requireApi();
  const prev = auctionEscrowForRough(player, roughId);
  if (!prev) return 0;
  const amount = money(prev.amount);
  setAuctionEscrow(player, { roughId, roundId: prev.roundId, amount: 0 });
  return amount;
}

export function refundAuctionEscrow(player, roughId, roughName = "") {
  const { money, releaseDeposit } = requireApi();
  const prev = auctionEscrowForRough(player, roughId);
  if (!prev) return 0;
  const amount = money(prev.amount);
  setAuctionEscrow(player, { roughId, roundId: prev.roundId, amount: 0 });
  if (amount > 0) {
    releaseDeposit(player, amount, `公盘落标退还：${roughName || roughId}`, {
      source: "auctionEscrowRefund",
      itemId: roughId,
      repEligible: false
    });
  }
  return amount;
}

export function refundStaleAuctionEscrows(roundId) {
  const { getState, normalizePlayer } = requireApi();
  const id = String(roundId || "");
  for (const player of playersMatching(getState().players, (entry) => Boolean(entry.auctionEscrow?.length))) {
    normalizePlayer(player);
    for (const entry of [...normalizeAuctionEscrow(player)]) {
      if (!id || entry.roundId === id) {
        refundAuctionEscrow(player, entry.roughId, entry.roughId);
      }
    }
  }
}

/**
 * Return deposits that no longer belong to a live bid in the active round.
 * This repairs saves captured after a round was removed/replaced or after an
 * interrupted bid update left only one side of the bid/escrow pair.
 */
export function reconcileAuctionEscrows() {
  const { getState, normalizePlayer } = requireApi();
  const state = getState();
  const rounds = new Map(auctionRoundsForState(state).filter((round) => !round.settledAt).map((round) => [round.id, round]));
  let count = 0;
  let refunded = 0;

  for (const player of playersMatching(state.players, (entry) => Boolean(entry.auctionEscrow?.length))) {
    normalizePlayer(player);
    for (const entry of [...normalizeAuctionEscrow(player)]) {
      const roughId = String(entry.roughId || "");
      const round = rounds.get(entry.roundId);
      const valid = round?.roughs?.some((rough) => rough.id === roughId)
        && round?.bids?.some((bid) => !bid.ai && bid.playerId === player.id && bid.roughId === roughId);
      if (valid) continue;
      refunded += refundAuctionEscrow(player, roughId, roughId);
      count += 1;
    }
  }

  return { changed: count > 0, count, refunded };
}

export function publicAuctionHalls(player) {
  const { getState } = requireApi();
  const level = playerLevelForExp(player?.exp);
  const state = getState();
  return AUCTION_HALLS.map((hall) => {
    const round = auctionRoundForHall(state, hall.id);
    return {
      id: hall.id,
      label: hall.label,
      requiredLevel: hall.requiredLevel,
      windowRate: hall.windowRate,
      windowMin: hall.windowMin,
      deposit: hall.deposit,
      entryFee: auctionEntryFee(hall),
      tone: hall.tone,
      priceNote: hall.priceNote,
      unlocked: level >= hall.requiredLevel,
      active: level >= hall.requiredLevel,
      next: false,
      entered: playerEnteredAuction(round, player?.id),
      startsAt: round?.startsAt,
      endsAt: round?.endsAt ?? round?.biddingEndsAt,
      myBidCount: (round?.bids || []).filter((bid) => bid.playerId === player?.id).length
    };
  });
}

export function auctionRoundDuration() {
  const { money, TIMING } = requireApi();
  const configured = TIMING.auction.duration ?? ((TIMING.auction.registration || 0) + (TIMING.auction.bidding || 0));
  return money(configured || 10 * 60 * 1000);
}

export function auctionEndsAt(round) {
  return Number(round?.endsAt ?? round?.biddingEndsAt ?? 0);
}

function auctionRoundTiming(now) {
  const rounds = auctionRoundsForState(requireApi().getState()).filter((round) => !round.settledAt);
  const duration = auctionRoundDuration();
  const latestEnd = Math.max(0, ...rounds.map(auctionEndsAt));
  // Keep the latest live deadline when repairing older, staggered halls so no
  // paid round is cut short. Renewals retain the cadence even after downtime.
  const startsAt = latestEnd > now
    ? latestEnd - duration
    : latestEnd > 0 ? latestEnd + Math.floor((now - latestEnd) / duration) * duration : now;
  return { startsAt, endsAt: startsAt + duration };
}

function synchronizeAuctionRoundTimes(now) {
  const timing = auctionRoundTiming(now);
  let changed = false;
  for (const round of auctionRoundsForState(requireApi().getState())) {
    // Expired rounds must settle at their original deadline, never reopen.
    if (round.settledAt || auctionEndsAt(round) <= now) continue;
    if (round.startsAt === timing.startsAt && round.endsAt === timing.endsAt && round.biddingEndsAt === timing.endsAt) continue;
    Object.assign(round, timing, { biddingEndsAt: timing.endsAt });
    changed = true;
  }
  return changed;
}

export function playerEnteredAuction(round, playerId) {
  return (round?.entries || []).some((entry) => entry.playerId === playerId);
}

export function createAuctionRound(now = Date.now(), hallSlot = null) {
  const {
    getState,
    makeRoughStone,
    randomUUID,
    DEFAULT_AUCTION_HALL_ID,
    addNews
  } = requireApi();
  const requestedHallId = typeof hallSlot === "string" ? hallSlot : hallSlot?.hallId;
  const hall = auctionHallForId(requestedHallId || DEFAULT_AUCTION_HALL_ID);
  const { startsAt, endsAt } = auctionRoundTiming(now);
  const state = getState();
  const roughs = createAuctionHallRoughs(hall.id, makeRoughStone, 8);
  // The shared legacy pool belongs to the primary hall. Additional halls only
  // expose their lots through paid, personalized publicAuctionSnapshots.
  if (!state.auction || (state.auction.hallId || "novice") === hall.id) {
    state.roughPool.splice(0, state.roughPool.length, ...roughs);
  }
  const round = storeAuctionRound(state, {
    id: randomUUID(),
    hallId: hall.id,
    hallLabel: hall.label,
    status: "live",
    startsAt,
    endsAt,
    biddingEndsAt: endsAt,
    entryFee: auctionEntryFee(hall),
    entries: [],
    roughs: [...roughs],
    bids: [],
    results: []
  });
  addNews(`${hall.label}已开场，前 8 分钟明拍，最后 2 分钟暗拍。`, "info");
  return round;
}

export function ensureAuctionRound(now = Date.now(), hallId = null) {
  const { getState } = requireApi();
  const state = getState();
  const target = hallId || state.auction?.hallId || "novice";
  const round = auctionRoundForHall(state, target);
  if (round && !round.settledAt && now < auctionEndsAt(round)) {
    synchronizeAuctionRoundTimes(now);
    return round;
  }
  if (round && !round.settledAt && now >= auctionEndsAt(round)) {
    settleAuctionIfDue(now, target);
    return auctionRoundForHall(state, target);
  }
  return createAuctionRound(now, target);
}

export function settleAuctionIfDue(now = Date.now(), hallId = null) {
  const state = requireApi().getState();
  const rounds = auctionRoundsForState(state).filter((round) => !hallId || (round.hallId || "novice") === hallId);
  if (!rounds.length) { ensureAuctionRound(now, hallId); return false; }
  let changed = false;
  for (const round of rounds) if (settleAuctionHallIfDue(now, round)) changed = true;
  return changed;
}

function settleAuctionHallIfDue(now, round) {
  const {
    getState,
    money,
    markInventoryItemNew,
    advanceTask,
    queueOfflineEvent,
    refreshPlayerReport,
    addNews,
    isPlayerOnline,
    emitUiEventToPlayer,
    uiMoney
  } = requireApi();
  const state = getState();
  if (round.settledAt || now < auctionEndsAt(round)) return false;
  const withAi = {
    ...round,
    bids: [
      ...(round.bids || []),
      ...round.roughs.flatMap((rough) => aiBidsForRough(rough, round.bids, 3))
    ]
  };
  const settled = settleAuctionRound(withAi, {
    now,
    bidderCanPay: (bid) => {
      if (bid.ai) return true;
      const bidder = state.players.get(bid.playerId);
      if (!bidder) return false;
      const escrow = auctionEscrowForRough(bidder, bid.roughId);
      return Boolean(escrow && money(escrow.amount) >= money(bid.amount));
    }
  });
  const transaction = attemptAtomicMutation([state], ({ afterCommit }) => {
  if (round === state.auction) state.latestAuctionResults = settled.results;
  state.auctionHistory.unshift({
    id: settled.id,
    roundId: settled.id,
    hallId: settled.hallId,
    hallLabel: settled.hallLabel,
    startsAt: settled.startsAt,
    endsAt: settled.endsAt ?? settled.biddingEndsAt,
    settledAt: settled.settledAt,
    results: settled.results
  });
  state.auctionHistory = state.auctionHistory.slice(0, 24);
  const humanBids = (round.bids || []).filter((bid) => bid?.playerId && !bid.ai);

  /** @type {Map<string, { wins: any[], losses: any[], spentTotal: number, refundedTotal: number, bidCount: number }>} */
  const reportMap = new Map();
  const touchReport = (playerId) => {
    const id = String(playerId || "");
    if (!id) return null;
    if (!reportMap.has(id)) {
      reportMap.set(id, { wins: [], losses: [], spentTotal: 0, refundedTotal: 0, bidCount: 0 });
    }
    return reportMap.get(id);
  };
  for (const entry of round.entries || []) touchReport(entry.playerId);
  for (const bid of humanBids) {
    const row = touchReport(bid.playerId);
    if (row) row.bidCount += 1;
  }

  for (const result of settled.results) {
    const rough = settled.roughs.find((item) => item.id === result.roughId);
    if (!rough) continue;
    const bidsOnRough = humanBids.filter((bid) => bid.roughId === rough.id);

    if (result.winnerId && !result.ai) {
      const winner = state.players.get(result.winnerId);
      if (winner) {
        consumeAuctionEscrow(winner, rough.id);
        state.roughPool = state.roughPool.filter((item) => item.id !== rough.id);
        winner.rough.push(markInventoryItemNew({
          ...rough,
          type: "rough",
          owner: winner.id,
          costBasis: { amount: money(result.price), complete: true },
          revealed: false,
          polished: false,
          materialStage: "rough"
        }));
        advanceTask(winner, "auction_win");
        if (winner.onboarding?.firstSaleAt && !winner.onboarding.completedAt) winner.onboarding.completedAt = now;
        const hall = auctionHallForId(settled.hallId);
        winner.stats ||= {};
        winner.stats.auctionWins = (winner.stats.auctionWins || 0) + 1;
        if (hall?.id === "legendary") winner.stats.legendaryHallWin = true;
        grantPlayerExp(winner, "auction_win", { hallLevel: hall?.requiredLevel || 1 });
        settlePlayerAchievements(winner);
        const winReport = touchReport(winner.id);
        if (winReport) {
          winReport.wins.push({
            roughId: rough.id,
            roughName: rough.name,
            price: money(result.price)
          });
          winReport.spentTotal += money(result.price);
        }
        queueOfflineEvent(winner, {
          type: "auction",
          text: `公盘已拍得${rough.name}，原石已入库。`,
          income: 0,
          expense: result.price,
          readyAt: settled.settledAt
        });
        refreshPlayerReport(winner);
        addNews(`${winner.name} 竞拍中标 ${rough.name}，成交 ${result.price}。`, "trade");
      }
      for (const bid of bidsOnRough) {
        if (bid.playerId === result.winnerId) continue;
        const loser = state.players.get(bid.playerId);
        if (!loser) continue;
        const refunded = refundAuctionEscrow(loser, rough.id, rough.name);
        const lossReport = touchReport(loser.id);
        if (lossReport) {
          lossReport.losses.push({
            roughId: rough.id,
            roughName: rough.name,
            myBid: money(bid.amount),
            winningPrice: money(result.price)
          });
          lossReport.refundedTotal += money(refunded);
        }
      }
      continue;
    }

    for (const bid of bidsOnRough) {
      const bidder = state.players.get(bid.playerId);
      if (!bidder) continue;
      const refunded = refundAuctionEscrow(bidder, rough.id, rough.name);
      const lossReport = touchReport(bidder.id);
      if (lossReport) {
        lossReport.losses.push({
          roughId: rough.id,
          roughName: rough.name,
          myBid: money(bid.amount),
          winningPrice: money(result.price || 0)
        });
        lossReport.refundedTotal += money(refunded);
      }
    }
    if (result.ai) {
      state.roughPool = state.roughPool.filter((item) => item.id !== rough.id);
    }
  }

  refundStaleAuctionEscrows(settled.id);
  deliverAuctionSettleReports(settled, reportMap, {
    money,
    uiMoney,
    isPlayerOnline,
    emitUiEventToPlayer,
    queueOfflineEvent,
    getState,
    afterCommit
  });
  addNews(`${settled.hallLabel || "公盘"}开标完成，新一场已接续。`, "trade");
  createAuctionRound(now, settled.hallId || "novice");
    return { ok: true };
  }, { message: "公盘结算未完成，所有竞拍资产已恢复。" });
  return transaction.ok === true;
}

function deliverAuctionSettleReports(settled, reportMap, deps) {
  const {
    money,
    uiMoney,
    isPlayerOnline,
    emitUiEventToPlayer,
    queueOfflineEvent,
    getState,
    afterCommit
  } = deps;
  const formatMoney = typeof uiMoney === "function" ? uiMoney : (n) => String(money(n));
  for (const [playerId, data] of reportMap.entries()) {
    const player = getState().players.get(playerId);
    if (!player) continue;
    const report = {
      playerId,
      roundId: settled.id,
      hallId: settled.hallId || "novice",
      hallLabel: settled.hallLabel || "公盘",
      settledAt: settled.settledAt,
      wins: data.wins,
      losses: data.losses,
      spentTotal: money(data.spentTotal),
      refundedTotal: money(data.refundedTotal),
      bidCount: data.bidCount
    };
    const showNow = !player.pendingAuctionSettle;
    if (showNow) player.pendingAuctionSettle = report;
    else (player.pendingAuctionSettles ||= []).push(report);
    const modal = buildAuctionSettleModalEvent(report, formatMoney);
    if (showNow && typeof isPlayerOnline === "function" && isPlayerOnline(player) && typeof emitUiEventToPlayer === "function") {
      const emit = () => emitUiEventToPlayer(player, modal);
      if (typeof afterCommit === "function") afterCommit(emit);
      else emit();
    } else if (typeof queueOfflineEvent === "function" && !data.wins.length) {
      // 中标已有逐条 offline 事件；全场零出价补一条摘要
      queueOfflineEvent(player, {
        type: "auction",
        text: data.bidCount > 0
          ? "公盘未拍得料子，竞拍款已退还。"
          : "公盘已结束，本场未提交出价。", income: money(data.refundedTotal),
        expense: 0,
        readyAt: settled.settledAt
      });
    }
  }
}

export function ackAuctionSettleForPlayer(player, roundId = "") {
  if (!player?.pendingAuctionSettle) return { ok: true, cleared: false };
  const pendingId = String(player.pendingAuctionSettle.roundId || "");
  if (roundId && pendingId && pendingId !== String(roundId)) {
    return { ok: true, cleared: false };
  }
  player.pendingAuctionSettle = (player.pendingAuctionSettles || []).shift() || null;
  return { ok: true, cleared: true };
}

export function processAuctionLifecycle(now = Date.now()) {
  const { getState } = requireApi();
  const state = getState();
  let changed = settleAuctionIfDue(now);
  for (const hall of AUCTION_HALLS) {
    if (!auctionRoundForHall(state, hall.id)) { ensureAuctionRound(now, hall.id); changed = true; }
  }
  if (synchronizeAuctionRoundTimes(now)) changed = true;
  return changed;
}

export function enterAuctionForPlayer(player, payload = {}, now = Date.now()) {
  const {
    getState,
    normalizePlayer,
    money,
    spendCash,
    DEFAULT_AUCTION_HALL_ID,
    addNews
  } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  normalizePlayer(player);
  const state = getState();
  const hallId = payload?.hallId || state.auction?.hallId || DEFAULT_AUCTION_HALL_ID;
  if (!AUCTION_HALLS.some((hall) => hall.id === hallId)) return { ok: false, message: "该公盘不存在。" };
  const hall = auctionHallForId(hallId);
  if (playerLevelForExp(player?.exp) < hall.requiredLevel) {
    return { ok: false, message: `需要经营 Lv.${hall.requiredLevel} 才能进入${hall.label}。` };
  }
  const round = ensureAuctionRound(now, hallId);
  if (round.settledAt || now >= auctionEndsAt(round)) return { ok: false, message: "本场拍卖已截止。" };
  const existing = (round.entries || []).find((entry) => entry.playerId === player.id);
  if (existing) return { ok: true, message: "已入场本场公盘。", entryFee: existing.fee, entry: existing };
  const remainMs = auctionEndsAt(round) - now;
  if (remainMs <= 10_000) {
    return { ok: false, message: "本场剩余不足 10 秒，已停止入场。" };
  }
  const entryFee = money(round.entryFee ?? auctionEntryFee(auctionHallForId(round.hallId)));
  if (entryFee > 0 && !spendCash(player, entryFee, `公盘入场费：${round.hallLabel || "公盘"}`, { source: "auctionEntry", itemId: round.id, repEligible: false })) {
    return { ok: false, message: `入场费需要 ${entryFee}。` };
  }
  const next = enterAuctionRound(round, { playerId: player.id, fee: entryFee, at: now });
  storeAuctionRound(state, next.round);
  addNews(`${player.name} 入场${round.hallLabel || "公盘"}。`, "info");
  return { ok: true, message: "入场成功。", entryFee, entry: next.entry };
}

export function joinAuctionForPlayer(player, payload = {}, now = Date.now()) {
  return enterAuctionForPlayer(player, payload, now);
}

function auctionRoundForAction(state, payload) {
  if (payload?.hallId) return auctionRoundForHall(state, payload.hallId);
  const roughId = typeof payload === "string" ? payload : payload?.roughId;
  return auctionRoundsForState(state).find((round) => round.roughs?.some((rough) => rough.id === roughId)) || state.auction;
}

export function submitAuctionBidForPlayer(player, payload, now = Date.now()) {
  const { getState, normalizePlayer, money, addNews } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  if (!payload || typeof payload !== "object") return { ok: false, message: "投标参数无效。" };
  normalizePlayer(player);
  const state = getState();
  const round = auctionRoundForAction(state, payload);
  if (!round) return { ok: false, message: "该公盘不存在或尚未开场。" };
  if (!round.settledAt && now >= auctionEndsAt(round)) {
    settleAuctionIfDue(now, round.hallId || "novice");
    return { ok: false, message: "本场拍卖已截止，已进入下一场。" };
  }
  if (round.settledAt || now >= auctionEndsAt(round)) {
    return { ok: false, message: "本轮公盘已截止。" };
  }
  if (!playerEnteredAuction(round, player.id)) {
    return { ok: false, message: "请先入场本场公盘。" };
  }
  const roughId = payload.roughId;
  const rough = round.roughs.find((item) => item.id === roughId);
  if (!rough) return { ok: false, message: "这块原石不在当前公盘。" };
  const bidAmount = money(payload.amount);
  if (bidAmount < rough.price) return { ok: false, message: "出价不能低于底价。" };
  const escrowResult = applyAuctionBidEscrow(player, rough, bidAmount, round, now);
  if (!escrowResult.ok) return escrowResult;
  const next = upsertBid(round, {
    playerId: player.id,
    roughId,
    amount: bidAmount,
    at: now
  });
  storeAuctionRound(state, next.round);
  addNews(`${player.name} 提交了 ${rough.name} 的竞价。`, "info");
  return {
    ok: true,
    message: escrowResult.previousAmount > 0 ? "出价已修改，抵押已按差额调整。" : "出价已提交，出价已抵押。", bid: next.bid,
    escrowed: escrowResult.escrowed,
    escrowDelta: escrowResult.delta
  };
}

export function normalizeWindowPayload(payload) {
  const { clamp } = requireApi();
  if (payload && typeof payload === "object") {
    return {
      roughId: payload.roughId,
      x: clamp(Number(payload.x) || 50, 18, 82),
      y: clamp(Number(payload.y) || 50, 18, 82)
    };
  }
  return {
    roughId: payload,
    x: Math.round(18 + Math.random() * 64),
    y: Math.round(18 + Math.random() * 64)
  };
}

export function windowTouchesColor(visual, x, y) {
  if (!visual?.belt) return false;
  const angle = Number(visual.beltAngle || 18) * Math.PI / 180;
  const dx = (Number(x || 50) - 50) / 50;
  const dy = (Number(y || 50) - 50) / 50;
  const cross = Math.abs(-dx * Math.sin(angle) + dy * Math.cos(angle));
  return cross < 0.28;
}

export function windowTouchesCrack(visual, x, y) {
  if (!visual?.crack) return false;
  return Math.abs(Number(x || 50) - 50) < 12 && Math.abs(Number(y || 50) - 50) < 28;
}

export function makeWindowReveal(rough, point = {}) {
  const { clamp, randomUUID, qualityByKey } = requireApi();
  const visual = rough.visual || {};
  const quality = qualityByKey(rough.trueQualityKey);
  const x = clamp(Number(point.x) || Math.round(18 + Math.random() * 64), 18, 82);
  const y = clamp(Number(point.y) || Math.round(18 + Math.random() * 64), 18, 82);
  return {
    id: randomUUID(),
    x,
    y,
    r: Math.round(9 + Math.random() * 5),
    seed: Math.floor((visual.seed || 1) + Math.random() * 10000),
    skin: visual.skin,
    vein: visual.vein,
    hasBelt: Boolean(windowTouchesColor(visual, x, y) || (visual.belt && Math.random() < 0.28)),
    hasCrack: Boolean(windowTouchesCrack(visual, x, y) || (visual.crack && Math.random() < 0.16)),
    translucency: clamp(visual.translucency ?? quality.score * 0.16, 0.12, 0.92),
    cotton: clamp(visual.cotton ?? 0.4, 0.08, 0.78)
  };
}

export function requestAuctionWindowForPlayer(player, payload, now = Date.now()) {
  const {
    getState,
    money,
    spendCash,
    OPEN_WINDOW_RATE,
    addNews
  } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const { roughId, x, y } = normalizeWindowPayload(payload);
  const state = getState();
  const round = auctionRoundForAction(state, payload);
  if (!round) return { ok: false, message: "该公盘不存在或尚未开场。" };
  if (!round.settledAt && now >= auctionEndsAt(round)) {
    settleAuctionIfDue(now, round.hallId || "novice");
    return { ok: false, message: "当前公盘已停止开窗，已进入下一场。" };
  }
  if (round.settledAt || now >= auctionEndsAt(round)) {
    return { ok: false, message: "当前公盘已停止开窗。" };
  }
  if (!playerEnteredAuction(round, player.id)) {
    return { ok: false, message: "请先入场本场公盘。" };
  }
  const rough = round.roughs.find((item) => item.id === roughId);
  if (!rough) return { ok: false, message: "这块原石不在当前公盘。" };
  if (rough.windows && rough.windows.length >= 1) {
    return { ok: false, message: `${rough.name}」每块原石仅可开窗一次，已经开过窗了。` };
  }
  const hall = AUCTION_HALLS.find((h) => h.id === round.hallId) || AUCTION_HALLS[0];
  const fee = auctionWindowFee(rough, {
    ...hall,
    windowRate: hall.windowRate ?? OPEN_WINDOW_RATE
  });
  if (!spendCash(player, fee, `开窗：${rough.name}`, { source: "window", itemId: rough.id })) {
    return { ok: false, message: `开窗费需要 ${fee}。` };
  }
  rough.windows = [...(rough.windows || []), makeWindowReveal(rough, { x, y })].slice(0, 1);
  addNews(`${player.name} 支付 ${fee} 为 ${rough.name} 请求开窗，公盘信息更新。`, "info");
  return { ok: true, message: "开窗完成。", rough };
}

market-service.js:
/**
 * Market service — stall listings + want board.
 * Call bindMarketApi(deps) once from server.js after helpers exist.
 */
import {
  wantMatchesItem,
  WANT_DURATIONS,
  WANT_ITEM_TYPES,
  WANT_RULES
} from "../../shared/domain/jade/jade-rules.js";
import {
  featureAccess,
  grantPlayerExp
} from "../../shared/domain/progression/player-progression.js";
import { settlePlayerAchievements } from "./achievement-rewards.js";
import { applyRepDelta } from "../../shared/domain/economy/metric-history.js";
import { pendingPayoutTotal } from "./economy-service.js";
import { attemptAtomicMutation } from "./atomic-mutation.js";
import { takeMarketEquipment, receiveMarketEquipment } from "./market-equipment.js";
import {
  MARKET_TAX,
  MARKET_TAX_PERCENT,
  MARKET_LISTING_MIN_PRICE,
  MARKET_LISTING_PER_PLAYER_CAP,
  MARKET_LISTING_GLOBAL_CAP,
  WANT_PER_PLAYER_CAP,
  WANT_GLOBAL_CAP,
  WANT_OFFERS_CAP
} from "../../shared/domain/economy/market-rules.js";

export {
  MARKET_TAX,
  MARKET_TAX_PERCENT,
  MARKET_LISTING_MIN_PRICE,
  MARKET_LISTING_PER_PLAYER_CAP,
  MARKET_LISTING_GLOBAL_CAP,
  WANT_PER_PLAYER_CAP,
  WANT_GLOBAL_CAP,
  WANT_OFFERS_CAP
};

let api = null;

export function bindMarketApi(nextApi) {
  api = nextApi;
}

function requireApi() {
  if (!api) throw new Error("market-service: bindMarketApi() was not called");
  return api;
}

function denyUnlessMarket(player) {
  const access = featureAccess(player, "market");
  if (!access.ok) return { ok: false, message: access.message, code: "FEATURE_LOCKED" };
  return null;
}

export function wantBucketName(type) {
  return type === "rough" ? "rough"
    : type === "material" ? "materials"
    : type === "slice" ? "slices" : "bracelets";
}

export function restoreWantOfferItem(player, offer) {
  if (!player || !offer?.item) return;
  const item = offer.item;
  if (!item.type) item.type = offer.type;
  player[wantBucketName(offer.type)].push(item);
}

export function refundWantOffers(want, exceptOfferId = null, options = {}) {
  const { getState, notifyPlayerToast } = requireApi();
  for (const offer of want.offers || []) {
    if (exceptOfferId && offer.id === exceptOfferId) continue;
    const seller = getState().players.get(offer.sellerId);
    if (seller) {
      restoreWantOfferItem(seller, offer);
      const notify = () => notifyPlayerToast(seller, "求购应征未成交，货品已退回库。");
      if (typeof options.afterCommit === "function") options.afterCommit(notify);
      else notify();
    }
  }
}

export function sortWantOffers(offers = []) {
  return offers.slice().sort((a, b) => {
    const priceDiff = Number(a.price || 0) - Number(b.price || 0);
    if (priceDiff !== 0) return priceDiff;
    return Number(a.createdAt || 0) - Number(b.createdAt || 0);
  });
}

export function removeWantById(wantId) {
  const { getState } = requireApi();
  const index = getState().wants.findIndex((want) => want.id === wantId);
  if (index >= 0) getState().wants.splice(index, 1);
}

/** 发布求购时冻结：预算 + 按预算计提的市场税。 */
export function wantEscrowAmountForBudget(budget) {
  const { money } = requireApi();
  const b = money(budget);
  return b + money(b * MARKET_TAX);
}

export function releaseWantEscrow(want, buyer, note) {
  const { money, releaseDeposit } = requireApi();
  const amount = money(want?.escrowAmount || 0);
  if (!want) return 0;
  want.escrowAmount = 0;
  if (!buyer || amount <= 0) return 0;
  releaseDeposit(buyer, amount, note, {
    source: "market-want-escrow-refund",
    wantId: want.id,
    repEligible: false
  });
  return amount;
}

/** 用已冻结金额支付成交总额；多退少补。无冻结时回退 spendCash。*/
export function payWantFromEscrow(want, buyer, total, itemName) {
  const { money, spendCash, releaseDeposit } = requireApi();
  const need = money(total);
  const escrow = money(want.escrowAmount || 0);
  if (escrow > 0) {
    if (escrow < need) {
      const gap = need - escrow;
      if (!spendCash(buyer, gap, `求购补差${itemName}`, {
        source: "market-want",
        itemId: want.id
      })) {
        return false;
      }
      want.escrowAmount = 0;
      return true;
    }
    const refund = escrow - need;
    if (refund > 0) {
      releaseDeposit(buyer, refund, `求购结余退还：${want.title || itemName}`, {
        source: "market-want-escrow-refund",
        wantId: want.id,
        repEligible: false
      });
    }
    want.escrowAmount = 0;
    return true;
  }
  return spendCash(buyer, need, `求购成交${itemName}`, {
    source: "market-want",
    wantId: want.id
  });
}

/**
 * 求购结算。lowest：取最低价；manual：须指定 offerId（到期不自动成交，仅关闭退还）— * @param {{ expired?: boolean, offerId?: string }} options
 */
export function settleWantInternal(want, buyer, options = {}) {
  const {
    getState,
    money,
    uiMoney,
    randomUUID,
    addItem,
    advanceTask,
    addNews,
    emitUiEventToPlayer,
    notifyPlayerToast
  } = requireApi();
  const expired = Boolean(options.expired);
  const pickedOfferId = options.offerId ? String(options.offerId) : "";
  const rule = WANT_RULES[want.rule] ? want.rule : "lowest";

  if (!want || !buyer || want.ownerId !== buyer.id) {
    return { ok: false, reason: "无权结算该求购。" };
  }
  if (want.status !== "open") {
    return { ok: false, reason: "求购正在结算或已关闭。" };
  }

  const state = getState();
  const referencedOffers = (want.offers || []).filter((offer) =>
    offer?.item
    && WANT_ITEM_TYPES.includes(offer.type)
    && state.players.has(offer.sellerId)
  );
  if (referencedOffers.length !== (want.offers || []).length) {
    want.offers = referencedOffers;
  }
  const candidates = sortWantOffers(
    referencedOffers.filter((offer) =>
      wantMatchesItem(want, offer.item, offer.type) && Number(offer.price) <= Number(want.budget)
    )
  );
  const participantRoots = [
    buyer,
    ...referencedOffers.map((entry) => state.players.get(entry.sellerId)).filter(Boolean),
    state.wants,
    state.news
  ];

  if (expired && (rule === "manual" || !candidates.length)) {
    return attemptAtomicMutation(
      participantRoots,
      ({ afterCommit }) => {
        refundWantOffers(want, null, { afterCommit });
        releaseWantEscrow(want, buyer, `求购关闭退还冻结：${want.title}`);
        removeWantById(want.id);
        afterCommit(() => notifyPlayerToast(
          buyer,
          candidates.length
            ? "征集结束，未手选成交，应征已退回，冻结资金已退还。" : "征集结束，无有效应征，冻结资金已退还。"));
        return { ok: true, filled: false };
      },
      { message: "求购关闭未完成，冻结资金与应征货品已恢复，请重试。" }
    );
  }

  if (!candidates.length) {
    return { ok: false, reason: "暂无有效应征。" };
  }

  let offer = candidates[0];
  if (rule === "manual" || pickedOfferId) {
    if (!pickedOfferId) {
      return { ok: false, reason: "请选择一条应征成交。" };
    }
    offer = candidates.find((o) => o.id === pickedOfferId);
    if (!offer) {
      return { ok: false, reason: "所选应征无效或已失效。" };
    }
  }

  const price = money(offer.price);
  const tax = money(price * MARKET_TAX);
  const total = price + tax;
  const isLowest = offer.id === candidates[0].id;
  const seller = state.players.get(offer.sellerId);
  return attemptAtomicMutation(
    participantRoots,
    ({ afterCommit }) => {
      want.status = "settling";
      if (!payWantFromEscrow(want, buyer, total, offer.item.name)) {
        want.status = "open";
        if (expired) {
          refundWantOffers(want, null, { afterCommit });
          releaseWantEscrow(want, buyer, `求购到期退还冻结：${want.title}`);
          removeWantById(want.id);
          afterCommit(() => emitUiEventToPlayer(buyer, {
            type: "modal",
            tone: "warn",
            title: "求购到期结算失败",
            body: `应征需支付 ${uiMoney(total)}（含税），资金不足。求购已关闭，应征已退回，冻结资金已退还。`
          }));
          return { ok: true, filled: false };
        }
        afterCommit(() => emitUiEventToPlayer(buyer, {
          type: "modal",
          tone: "warn",
          title: "资金不足",
          body: `该应征需支付 ${uiMoney(total)}（成交价 ${uiMoney(price)} + 税费 ${uiMoney(tax)}）。请检查冻结与可用现金后再成交，或撤销求购。`
        }));
        return { ok: false, reason: "cash" };
      }

      requireApi().earnCash(seller, price, `交易行成交：${offer.item.name}`, { source: "market-payout", itemId: offer.item.id });
      seller.soldCount = (seller.soldCount || 0) + 1;
      applyRepDelta(seller, 2, `交易行卖出：${offer.item.name}`, { source: "market_sell", itemId: offer.item?.id });
      seller.stats.tradeCount += 1;
      grantPlayerExp(seller, "market_sell");
      settlePlayerAchievements(seller);

      const added = addItem(buyer, offer.item, { type: offer.type, acquisitionCost: total });
      if (!added) throw new Error("market-service: buyer inventory rejected want item");
      buyer.stats.tradeCount += 1;
      grantPlayerExp(buyer, "market_buy");
      settlePlayerAchievements(buyer);
      advanceTask(buyer, "market_buy");

      refundWantOffers(want, offer.id, { afterCommit });
      want.escrowAmount = 0;
      removeWantById(want.id);
      addNews(
        `${buyer.name} 求购成交：从 ${offer.sellerName} 处以 ${uiMoney(price)} 购入 ${offer.item.name}。`,
        "trade"
      );

      const modeLabel = rule === "manual"
        ? (isLowest ? "手选成交（当前最低价）" : "手选成交")
        : "已按最低价成交";
      afterCommit(() => notifyPlayerToast(seller, "求购应征已成交。"));
      afterCommit(() => emitUiEventToPlayer(buyer, {
        type: "modal",
        tone: "trade",
        title: "求购成交",
        subtitle: offer.item.name,
        body: `${modeLabel}。未用完的冻结资金已退回。`
      }));
      return { ok: true, filled: true, offerId: offer.id };
    },
    { message: "求购成交未完成，买卖双方资产已恢复，请重试。" }
  );
}

export function processExpiredWants(now = Date.now()) {
  const { getState } = requireApi();
  const state = getState();
  const due = state.wants.filter((want) => {
    if (want.status !== "open") return false;
    const expiresAt = Number(want.expiresAt || 0);
    if (expiresAt <= 0) return false;
    return expiresAt <= now;
  });
  if (!due.length) return false;
  for (const want of due) {
    const buyer = state.players.get(want.ownerId);
    if (!buyer) {
      refundWantOffers(want);
      removeWantById(want.id);
      continue;
    }
    settleWantInternal(want, buyer, { expired: true });
  }
  return true;
}

/** Repair cross-player market references after loading a persisted world. */
export function reconcileMarketReferences() {
  const { getState } = requireApi();
  const state = getState();
  let orphanListings = 0;
  let orphanWants = 0;
  let orphanOffers = 0;
  let reopenedWants = 0;

  for (let index = state.listings.length - 1; index >= 0; index -= 1) {
    const listing = state.listings[index];
    if (listing?.item && state.players.has(listing.ownerId)) continue;
    state.listings.splice(index, 1);
    orphanListings += 1;
  }

  for (let index = state.wants.length - 1; index >= 0; index -= 1) {
    const want = state.wants[index];
    const buyer = want?.ownerId ? state.players.get(want.ownerId) : null;
    if (!want || !buyer) {
      if (want) refundWantOffers(want);
      state.wants.splice(index, 1);
      orphanWants += 1;
      continue;
    }
    if (want.status === "settling") {
      want.status = "open";
      reopenedWants += 1;
    }
    if (!Array.isArray(want.offers)) {
      want.offers = [];
      continue;
    }
    for (let offerIndex = want.offers.length - 1; offerIndex >= 0; offerIndex -= 1) {
      const offer = want.offers[offerIndex];
      if (offer?.item && state.players.has(offer.sellerId)) continue;
      want.offers.splice(offerIndex, 1);
      orphanOffers += 1;
    }
  }

  const changed = orphanListings + orphanWants + orphanOffers + reopenedWants > 0;
  return { changed, orphanListings, orphanWants, orphanOffers, reopenedWants };
}

export function listItemForPlayer(player, { type, itemId, price } = {}) {
  const { getState, money, takeItem, randomUUID, advanceTask, addNews } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const locked = denyUnlessMarket(player);
  if (locked) return locked;
  const listingPrice = money(Number(price));
  if (!["rough", "material", "slice", "bracelet", "equipment"].includes(type) || !Number.isFinite(Number(price)) || listingPrice < MARKET_LISTING_MIN_PRICE) {
    return { ok: false, message: "挂单参数无效。" };
  }
  const state = getState();
  const mine = state.listings.filter((listing) => listing.ownerId === player.id).length;
  if (mine >= MARKET_LISTING_PER_PLAYER_CAP) {
    return {
      ok: false,
      message: `每位掌柜最多同时挂出 ${MARKET_LISTING_PER_PLAYER_CAP} 件货品。`,
      code: "PLAYER_MARKET_FULL"
    };
  }
  if (state.listings.length >= MARKET_LISTING_GLOBAL_CAP) {
    return { ok: false, message: "交易行货架已满，请稍后再试。", code: "MARKET_FULL" };
  }
  return attemptAtomicMutation([player, state.listings, state.news], () => {
    const equipment = type === "equipment" ? takeMarketEquipment(player, itemId, state) : null;
    if (equipment && !equipment.ok) return equipment;
    const item = equipment ? equipment.item : takeItem(player, type, itemId);
    if (!item) return { ok: false, message: "库存中找不到该货品。" };
    state.listings.unshift({
      id: randomUUID(),
      ownerId: player.id,
      ownerName: player.name,
      type,
      item,
      price: listingPrice,
      createdAt: Date.now()
    });
    advanceTask(player, "market_sell");
    addNews(`${player.name} 在交易行挂出 ${item.name}，标价${listingPrice}。`, "trade");
    return { ok: true, message: "已挂牌。", price: listingPrice, item };
  });
}

export function buyListingForPlayer(player, listingId) {
  const {
    getState,
    money,
    spendCash,
    randomUUID,
    addItem,
    advanceTask,
    addNews
  } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const locked = denyUnlessMarket(player);
  if (locked) return locked;
  const state = getState();
  const index = state.listings.findIndex((listing) => listing.id === listingId);
  if (index < 0) return { ok: false, message: "挂单不存在。" };
  const listing = state.listings[index];
  if (listing.ownerId === player.id) return { ok: false, message: "不能购买自己的挂单。" };
  const seller = state.players.get(listing.ownerId);
  if (!seller || !listing.item) {
    state.listings.splice(index, 1);
    return {
      ok: false,
      code: "STALE_LISTING",
      message: "卖家或货品已失效，挂单已自动下架。"
    };
  }
  const tax = money(listing.price * MARKET_TAX);
  const total = listing.price + tax;
  return attemptAtomicMutation(
    [player, seller, state.listings, state.news],
    () => {
      if (!spendCash(player, total, `交易行购入：${listing.item.name}（含税 ${tax}）`, { source: "market", itemId: listing.item.id })) {
        return { ok: false, message: `资金不足（含 ${MARKET_TAX_PERCENT}% 市场税）。` };
      }
      requireApi().earnCash(seller, listing.price, `交易行成交：${listing.item.name}`, { source: "market-payout", itemId: listing.item.id });
      seller.soldCount = (seller.soldCount || 0) + 1;
      applyRepDelta(seller, 2, `交易行卖出：${listing.item.name}`, { source: "market_sell", itemId: listing.item?.id });
      seller.stats.tradeCount += 1;
      grantPlayerExp(seller, "market_sell");
      settlePlayerAchievements(seller);
      const added = listing.type === "equipment"
        ? receiveMarketEquipment(player, listing.item, total, listing.ownerId)
        : addItem(player, listing.item, { type: listing.type, acquisitionCost: total });
      if (!added) throw new Error("market-service: buyer inventory rejected listing item");
      advanceTask(player, "market_buy");
      player.stats.tradeCount += 1;
      grantPlayerExp(player, "market_buy");
      settlePlayerAchievements(player);
      state.listings.splice(index, 1);
      addNews(`${player.name} 从 ${listing.ownerName} 手里买下 ${listing.item.name}，成交 ${listing.price}。`, "trade");
      return {
        ok: true,
        message: "交易成交。", listing,
        tax,
        total
      };
    },
    { message: "交易未完成，买卖双方资产已恢复，请重试。" }
  );
}

export function withdrawListingForPlayer(player, listingId) {
  const { getState, addNews } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const state = getState();
  const index = state.listings.findIndex((listing) => listing.id === listingId);
  if (index < 0) return { ok: false, message: "挂单不存在。" };
  const listing = state.listings[index];
  if (listing.ownerId !== player.id) return { ok: false, message: "只能撤下自己的挂单。" };
  return attemptAtomicMutation([player, state.listings, state.news], () => {
    if (listing.type === "equipment") receiveMarketEquipment(player, listing.item);
    else player[wantBucketName(listing.type)].push(listing.item);
    state.listings.splice(index, 1);
    addNews(`${player.name} 撤回了交易行挂单 ${listing.item.name}。`, "trade");
    return { ok: true, message: listing.type === "equipment" ? "已撤单，设备已退回工坊。" : "已撤单，退回库存。", listing };
  });
}

export function acceptMarketOfferForPlayer(player, listingId, offerId) {
  const { getState, earnCash, addNews, uiMoney } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const state = getState();
  const listing = state.listings.find((entry) => entry.id === listingId);
  if (!listing || listing.ownerId !== player.id) return { ok: false, message: "挂单不存在或不属于你。" };
  if (listing.type === "equipment") return { ok: false, message: "设备暂不参与批发商收购。" };
  const offer = listing.npcOffer;
  if (!offer || offer.id !== offerId) return { ok: false, message: "收购报价已失效。" };
  const remaining = remainingMarketLiquidity(player);
  if (remaining.count <= 0 || remaining.cash < offer.amount) {
    return { ok: false, message: "今日批发额度不足，请明日再来或选择其他销售渠道。" };
  }
  return attemptAtomicMutation([player, state.listings, state.news], () => {
    bookMarketLiquidity(player, offer.amount);
    state.listings.splice(state.listings.indexOf(listing), 1);
    earnCash(player, offer.amount, `批发商收购：${listing.item.name}`, { source: "market-payout", itemId: listing.item.id });
    player.soldCount = (player.soldCount || 0) + 1;
    player.stats.tradeCount += 1;
    applyRepDelta(player, 1, `批发成交：${listing.item.name}`, { source: "market_sell", itemId: listing.item.id });
    grantPlayerExp(player, "market_sell");
    settlePlayerAchievements(player);
    addNews(`${player.name} 的${listing.item.name}以 ${uiMoney(offer.amount)} 成交给批发商。`, "trade");
    return { ok: true, listing, amount: offer.amount, message: "出售成功。" };
  });
}

export function collectMarketPayoutForPlayer(player) {
  const { earnCash, addNews, uiMoney } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const payout = pendingPayoutTotal(player.payouts);
  if (payout.code === "EMPTY_PAYOUT") {
    return { ok: false, message: "没有可领取的交易行收益。" };
  }
  if (!payout.ok) {
    return {
      ok: false,
      code: payout.code,
      message: "交易行收益数据异常，记录已保留，请稍后重试。"
    };
  }
  const total = payout.total;
  earnCash(player, total, "交易行收益领取", { source: "market-payout" });
  player.payouts = [];
  addNews(`${player.name} 领取了交易行收益 ${uiMoney(total)}。`, "trade");
  return { ok: true, message: "已领取。", total };
}

export function postWantForPlayer(player, payload = {}) {
  const {
    getState,
    money,
    clamp,
    holdDeposit,
    randomUUID,
    addNews,
    uiMoney
  } = requireApi();
  if (!player) return { ok: false, message: "玩家未就绪，请刷新后重试。" };
  const locked = denyUnlessMarket(player);
  if (locked) return locked;
  const title = String(payload.title || "").trim().slice(0, 40);
  const itemType = String(payload.itemTypes?.[0] || payload.itemType || "").trim();
  const durationKey = String(payload.durationKey || "10m");
  const duration = WANT_DURATIONS[durationKey];
  const rule = WANT_RULES[payload.rule] ? String(payload.rule) : "lowest";
  const budget = money(payload.budget);
  const minScore = clamp(Math.round(Number(payload.minScore) || 1), 1, 6);
  const note = String(payload.note || "").trim().slice(0, 80);
  const qualityKey = payload.qualityKey ? String(payload.qualityKey).trim() : "";
  let acceptedKinds = Array.isArray(payload.acceptedKinds)
    ? payload.acceptedKinds.map((k) => String(k)).filter(Boolean).slice(0, 12)
    : [];

  if (!title) return { ok: false, message: "请填写求购标题。" };
  if (!WANT_ITEM_TYPES.includes(itemType)) return { ok: false, message: "请选择求购品类。" };
  if (!duration) return { ok: false, message: "征集时长无效。" };
  if (budget < 100) return { ok: false, message: "预算至少 ¥100。" };
  if (itemType === "bracelet") {
    if (!acceptedKinds.length) acceptedKinds = ["bracelet"];
  } else {
    acceptedKinds = [];
  }
  if (qualityKey && !["bean", "glutinous", "stickyIce", "ice", "highIce", "glass", "violet", "red", "ink", "icy", "imperial"].includes(qualityKey)) {
    return { ok: false, message: "种水筛选无效。" };
  }
  const state = getState();
  const mineOpen = state.wants.filter((w) => w.ownerId === player.id && w.status === "open").length;
  if (mineOpen >= WANT_PER_PLAYER_CAP) {
    return { ok: false, message: `同时最多发布 ${WANT_PER_PLAYER_CAP} 条进行中求购。` };
  }
  if (state.wants.length >= WANT_GLOBAL_CAP) {
    return { ok: false, message: "求购板已满，稍后再试。" };
  }

  const escrowAmount = wantEscrowAmountForBudget(budget);
  if (!holdDeposit(player, escrowAmount, `求购冻结${title}（预算含税）`, {
    source: "market-want-escrow",
    repEligible: false
  })) {
    return { ok: false, message: `可用现金不足，发布需冻结 ${uiMoney(escrowAmount)}（预留 ${MARKET_TAX_PERCENT}% 税费）。` };
  }

  const now = Date.now();
  const want = {
    id: randomUUID(),
    ownerId: player.id,
    ownerName: player.name,
    title,
    note,
    itemTypes: [itemType],
    acceptedKinds,
    qualityKey: itemType === "bracelet" ? "" : qualityKey,
    minScore,
    budget,
    escrowAmount,
    durationKey,
    rule,
    status: "open",
    createdAt: now,
    expiresAt: duration.ms > 0 ? now + duration.ms : 0,
    offers: []
  };
  state.wants.unshift(want);
  addNews(`${player.name} 发布求购「${title}」，预算 ${uiMoney(budget)}。`, "trade");
  return { ok: true, message: "求购已发布。", want, escrowAmount };
}

export function cancelWantForPlayer(player, wantId) {
  const { getState, addNews, uiMoney } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const state = getState();
  const want = state.wants.find((w) => w.id === wantId);
  if (!want) return { ok: false, message: "求购不存在。" };
  if (want.ownerId !== player.id) return { ok: false, message: "只能撤销自己的求购。" };
  if (want.status !== "open") return { ok: false, message: "求购正在结算，无法撤销。" };
  const sellers = (want.offers || [])
    .map((offer) => state.players.get(offer.sellerId))
    .filter(Boolean);
  return attemptAtomicMutation(
    [player, ...sellers, state.wants, state.news],
    ({ afterCommit }) => {
      refundWantOffers(want, null, { afterCommit });
      const refunded = releaseWantEscrow(want, player, `撤销求购退还冻结：${want.title}`);
      removeWantById(want.id);
      addNews(`${player.name} 撤销了求购「${want.title}」。`, "trade");
      return {
        ok: true,
        message: "已撤销求购。",
        refunded
      };
    },
    { message: "求购撤销未完成，冻结资金与应征货品已恢复，请重试。" }
  );
}

export function applyWantForPlayer(player, { wantId, type, itemId, price } = {}) {
  const { getState, money, takeItem, randomUUID, uiMoney } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const locked = denyUnlessMarket(player);
  if (locked) return locked;
  const want = getState().wants.find((w) => w.id === wantId && w.status === "open");
  if (!want) return { ok: false, message: "求购不存在或已结束。" };
  if (want.ownerId === player.id) return { ok: false, message: "不能应征自己的求购。" };
  if (!WANT_ITEM_TYPES.includes(type)) return { ok: false, message: "货品类型无效。" };
  if (!(want.itemTypes || []).includes(type)) return { ok: false, message: "品类不符合求购要求。" };
  const offerPrice = money(price);
  if (offerPrice < 100) return { ok: false, message: "报价至少 ¥100。" };
  if (offerPrice > want.budget) {
    return { ok: false, message: `报价不能超过预算 ${uiMoney(want.budget)}。` };
  }
  if ((want.offers || []).length >= WANT_OFFERS_CAP) {
    return { ok: false, message: "该求购应征已满。" };
  }
  if ((want.offers || []).some((o) => o.sellerId === player.id)) {
    return { ok: false, message: "你已应征过该求购，请先撤回再改。" };
  }
  const item = takeItem(player, type, itemId);
  if (!item) return { ok: false, message: "库存中找不到该货品。" };
  if (!wantMatchesItem(want, item, type)) {
    if (!item.type) item.type = type;
    player[wantBucketName(type)].push(item);
    return { ok: false, message: "货品不符合求购条件。" };
  }
  if (!item.type) item.type = type;
  want.offers.push({
    id: randomUUID(),
    sellerId: player.id,
    sellerName: player.name,
    type,
    item,
    price: offerPrice,
    createdAt: Date.now()
  });
  return { ok: true, message: "已应征。", offerPrice };
}

export function withdrawWantOfferForPlayer(player, { wantId, offerId } = {}) {
  const { getState } = requireApi();
  if (!player) return { ok: false, message: "未找到玩家。" };
  const want = getState().wants.find((w) => w.id === wantId && w.status === "open");
  if (!want) return { ok: false, message: "求购不存在或已结束。" };
  const index = (want.offers || []).findIndex((o) => o.id === offerId);
  if (index < 0) return { ok: false, message: "应征不存在。" };
  const offer = want.offers[index];
  if (offer.sellerId !== player.id) return { ok: false, message: "只能撤回自己的应征。" };
  want.offers.splice(index, 1);
  restoreWantOfferItem(player, offer);
  return { ok: true, message: "已撤回应征。" };
}

export function settleWantForPlayer(player, payload) {
  const { getState } = requireApi();
  if (!player) return { ok: false, reason: "未找到玩家。" };
  const wantId = typeof payload === "string" ? payload : payload?.wantId;
  const offerId = typeof payload === "object" && payload ? payload.offerId : null;
  const want = getState().wants.find((w) => w.id === wantId);
  if (!want) return { ok: false, reason: "求购不存在。" };
  return settleWantInternal(want, player, { expired: false, offerId });
}
