import { requireApi } from "./context.js";
import { isNpcBlackStall } from "../../../shared/domain/blackmarket/npc-rules.js";
import { reconcileResourceListings } from "./resources.js";
import {
  findEscrowItemForOrder,
  paySellerNow,
  releaseDepositSafe,
  removeEscrowItemFromSeller,
  removeStallFromState,
  returnHeldItemToBuyer
} from "./helpers.js";

const RECOVERABLE_ORDER_STATUSES = new Set(["pending", "escrow", "delivered"]);
const INVENTORY_BUCKETS = ["rough", "materials", "slices", "bracelets"];

function playerHasItem(player, itemId) {
  const id = String(itemId || "");
  if (!player || !id) return false;
  return INVENTORY_BUCKETS.some((bucket) =>
    (player[bucket] || []).some((item) => String(item?.id || "") === id)
  );
}

function recoverLegacyBlackListings(state, summary) {
  const legacyListings = state.blackListings;
  if (!Array.isArray(legacyListings) || legacyListings.length === 0) return;
  const { addItem } = requireApi();

  for (const listing of legacyListings) {
    summary.legacyListings += 1;
    const owner = listing?.ownerId ? state.players?.get?.(listing.ownerId) : null;
    const item = listing?.item;
    if (!owner || !item?.id) {
      summary.discardedLegacyListings += 1;
      continue;
    }
    if (!playerHasItem(owner, item.id)) {
      addItem(owner, item, { type: listing.type || item.type, asNew: false });
    }
    if (playerHasItem(owner, item.id)) {
      summary.recoveredLegacyItems += 1;
    } else {
      summary.discardedLegacyListings += 1;
    }
  }

  legacyListings.length = 0;
  summary.changed = true;
}

function outstandingOrderFee(order) {
  const price = Math.max(0, Number(order?.price) || 0);
  const released = Math.max(0, Number(order?.feeReleased) || 0);
  const refunded = Math.max(0, Number(order?.feeRefunded) || 0);
  return Math.max(0, price - released - refunded);
}

function refundOutstandingOrderFee(order, buyer) {
  const amount = outstandingOrderFee(order);
  if (!buyer || amount <= 0) return 0;
  const refunded = releaseDepositSafe(
    buyer,
    amount,
    `黑市服务存档恢复退款：${order.title || "技术单"}`,
    { source: "blackmarket-service-recovery" }
  );
  order.feeRefunded = Math.max(0, Number(order.feeRefunded) || 0) + refunded;
  return refunded;
}

function payOutstandingOrderFee(order, seller) {
  const amount = outstandingOrderFee(order);
  if (!seller || amount <= 0) return 0;
  const released = paySellerNow(
    seller,
    amount,
    `服务存档恢复·${order.title || "技术单"}`,
    { source: "blackmarket-service-recovery-payout" }
  );
  order.feeReleased = Math.max(0, Number(order.feeReleased) || 0) + released;
  return released;
}

function discardEscrowItem(order, seller) {
  if (!seller) return false;
  const row = findEscrowItemForOrder(seller, order.id);
  if (!row) return false;
  if (row.inDelivery) {
    let pending = row;
    while (pending?.inDelivery) {
      if (!removeEscrowItemFromSeller(seller, pending.type, pending.item)) break;
      pending = findEscrowItemForOrder(seller, order.id);
    }
    return true;
  }
  if (row.inJob && row.job) {
    const jobs = seller.jobs || [];
    const index = jobs.findIndex((job) => job === row.job || job?.id === row.job?.id);
    if (index < 0) return false;
    jobs.splice(index, 1);
    return true;
  }
  return Boolean(removeEscrowItemFromSeller(seller, row.type, row.item));
}

function recoverOrphanServiceOrder(order, state, now, summary) {
  if (!RECOVERABLE_ORDER_STATUSES.has(order?.status)) return false;
  const buyer = state.players?.get?.(order.buyerId);
  const seller = state.players?.get?.(order.sellerId);
  if (buyer && seller) return false;

  if (order.status === "delivered" && !buyer && seller) {
    summary.releasedFees += payOutstandingOrderFee(order, seller);
    order.status = "completed";
    order.completedAt = now;
    order.submitMode = "recovered_missing_buyer";
  } else {
    let itemRecovered = false;
    if (buyer && order.heldItem?.item) {
      itemRecovered = returnHeldItemToBuyer(order, state);
    } else if (!buyer && seller && order.status === "escrow") {
      if (discardEscrowItem(order, seller)) summary.discardedItems += 1;
    }
    if (buyer) {
      summary.refundedFees += refundOutstandingOrderFee(order, buyer);
      if (!itemRecovered && order.status !== "delivered") summary.unrecoverableItems += 1;
    }
    if (!buyer) order.heldItem = null;
    order.status = buyer && order.status === "delivered" ? "refunded" : "cancelled";
    order.cancelledAt = now;
    order.submitMode = !buyer && !seller
      ? "recovered_missing_parties"
      : !buyer
        ? "recovered_missing_buyer"
        : "recovered_missing_seller";
  }

  summary.orphanOrders += 1;
  return true;
}

function recoverOrphanBlindDraw(stall, state, summary) {
  const draw = stall?.blindDraw;
  if (!draw) return;
  const buyer = state.players?.get?.(draw.buyerId);
  if (!buyer) return;

  const first = (draw.candidates || []).find((row) => row?.item);
  if (first) {
    const { addItem } = requireApi();
    if (!first.item.type && first.type) first.item.type = first.type;
    addItem(buyer, first.item, { type: first.type || first.item.type, asNew: true });
    summary.recoveredBlindItems += 1;
    return;
  }

  if (draw.entryPaid !== false) {
    summary.refundedBlindFees += releaseDepositSafe(
      buyer,
      Math.max(0, Number(draw.price) || 0),
      `黑市盲盒存档恢复退款：${stall.title || "盲盒"}`,
      { source: "blackmarket-blind-recovery" }
    );
  }
}

/**
 * Repair persisted black-market records whose player references no longer
 * exist. Valid trades are left untouched; only impossible owner/order links
 * are closed so money, held items, and workshop jobs cannot remain stuck.
 */
export function reconcileBlackmarketReferences(state, now = Date.now()) {
  const summary = {
    changed: false,
    orphanStalls: 0,
    orphanOrders: 0,
    refundedFees: 0,
    releasedFees: 0,
    recoveredBlindItems: 0,
    refundedBlindFees: 0,
    discardedItems: 0,
    unrecoverableItems: 0,
    legacyListings: 0,
    recoveredLegacyItems: 0,
    discardedLegacyListings: 0
  };

  recoverLegacyBlackListings(state, summary);

  for (const order of state.blackServiceOrders || []) {
    if (recoverOrphanServiceOrder(order, state, now, summary)) summary.changed = true;
  }

  for (const stall of [...(state.blackStalls || [])]) {
    if (isNpcBlackStall(stall)) continue;
    if (state.players?.has?.(stall.ownerId)) continue;
    recoverOrphanBlindDraw(stall, state, summary);
    if (removeStallFromState(state, stall)) {
      summary.orphanStalls += 1;
      summary.changed = true;
    }
  }

  if (reconcileResourceListings(state)) summary.changed = true;
  return summary;
}

blackmarket/resources.js:
import { requireApi } from "./context.js";
import { resourceBucket, resourceSaleBlock, isBlackmarketResource } from "../../../shared/domain/blackmarket/bm-resources.js";
import { MAX_WORKERS, isStarterWorkerId, normalizeDismissedStarterIds } from "../../systems/employee-system.js";
import { enterEmployeePayrollDay, employeeRecruitmentBlock, recordEmployeePayrollRoster, settleEmployeePayroll } from "../../systems/employee-payroll.js";
import { setAcquisitionCost } from "../../../shared/domain/economy/item-cost.js";

export function ownedResource(player, type, id) {
  return player?.workshop?.[resourceBucket(type)]?.find((item) => item.id === id);
}

export function lockResource(player, type, id) {
  const item = ownedResource(player, type, id);
  const blocked = resourceSaleBlock(player, type, item, requireApi().getState().blackServiceOrders || []);
  if (blocked) return { ok: false, message: blocked };
  item.blackmarketListingId = requireApi().randomUUID();
  return { ok: true, item: { ...structuredClone(item), type }, listingId: item.blackmarketListingId };
}

export function unlockResource(player, type, id) {
  const item = ownedResource(player, type, id);
  if (item) delete item.blackmarketListingId;
}

export function resourceBuyerBlock(player, type, item, price) {
  const legacyStarter = type === "employee" && isStarterWorkerId(item.id);
  if (!legacyStarter && (player?.workshop?.[resourceBucket(type)] || []).some((entry) => entry.id === item.id)) return "资源编号冲突，请重新选择商品。";
  if (type === "employee") {
    if ((player.workshop?.workers || []).length >= MAX_WORKERS) return "员工人数已经达到 8 人上限。";
    const blocked = employeeRecruitmentBlock(player);
    if (blocked) return blocked.message;
  }
  if (!Number.isSafeInteger(price) || price < 100 || player.cash < price) return "资金不足或报价无效。";
  return null;
}

export function receiveResource(player, type, item, price, sellerId = "npc") {
  const { spendCash, randomUUID } = requireApi();
  const now = Date.now();
  if (type === "employee") {
    enterEmployeePayrollDay(player, { spendCash, now, reason: "continued" });
    const blocked = employeeRecruitmentBlock(player, now);
    if (blocked) throw new Error(blocked.message);
  }
  if (resourceBuyerBlock(player, type, item, price)) throw new Error("接收条件已变化，请重新确认。");
  const acquired = structuredClone(item);
  // Legacy starter IDs describe a local roster slot shared by every player.
  // Once transferred, this employee gets a persistent globally unique identity.
  if (type === "employee" && isStarterWorkerId(acquired.id)) acquired.id = randomUUID();
  if (!acquired.id || (player.workshop?.[resourceBucket(type)] || []).some((entry) => entry.id === acquired.id)) throw new Error("资源编号冲突，请重新选择商品。");
  if (!spendCash(player, price, `黑市${type === "employee" ? "转聘" : "购入"}：${item.name}`, { source: "blackmarket", itemId: acquired.id })) throw new Error("资金不足。");
  delete acquired.blackmarketListingId;
  delete acquired.workerId;
  delete acquired.busy;
  delete acquired.price;
  delete acquired.value;
  delete acquired._type;
  acquired.resourceOrigin = "blackmarket";
  acquired.acquisitionPrice = price;
  setAcquisitionCost(acquired, price);
  acquired.acquiredAt = now;
  acquired.tradeHistory = [...(acquired.tradeHistory || []), { sellerId, buyerId: player.id, price, at: now }].slice(-20);
  if (type === "employee") acquired.payrollAt = now;
  player.workshop ||= {};
  (player.workshop[resourceBucket(type)] ||= []).push(acquired);
  if (type === "employee") recordEmployeePayrollRoster(player, now);
  return acquired;
}

export function releaseSoldResource(seller, type, row) {
  const item = ownedResource(seller, type, row.item.id);
  if (!item || item.blackmarketListingId !== row.id) throw new Error("挂牌资源已失效。");
  let payroll;
  if (type === "employee") payroll = settleEmployeePayroll(seller, {
    spendCash: requireApi().spendCash, closingWorkerId: item.id, closingReason: "transfer",
    closingWorkerOnly: !requireApi().isPlayerOnline?.(seller)
  });
  if (type === "employee" && isStarterWorkerId(item.id)) {
    seller.workshop.dismissedStarterIds = normalizeDismissedStarterIds([...(seller.workshop.dismissedStarterIds || []), item.id]);
  }
  seller.workshop[resourceBucket(type)] = seller.workshop[resourceBucket(type)].filter((entry) => entry.id !== item.id);
  for (const device of seller.workshop.devices || []) if (type === "employee" && device.workerId === item.id) delete device.workerId;
  if (type === "equipment") {
    for (const key of ["selectedDeviceId", "defaultDeviceId"]) if (seller.workshop[key] === item.id) delete seller.workshop[key];
  }
  return payroll;
}

// Rebuild locks from the authoritative shelves after loading a save. Never clone a
// resource back into a roster: listed resources already remain with their owner.
export function reconcileResourceListings(state) {
  const expected = new Map();
  let changed = false;
  for (const stall of state.blackStalls || []) {
    if (stall.npc || stall.type !== "goods") continue;
    const owner = state.players?.get?.(stall.ownerId);
    stall.items = (stall.items || []).filter((row) => {
      if (!isBlackmarketResource(row.type)) return true;
      const item = ownedResource(owner, row.type, row.item?.id);
      const key = `${stall.ownerId}:${row.type}:${row.item?.id}`;
      if (!item || expected.has(key)) { changed = true; return false; }
      expected.set(key, row.id);
      if (item.blackmarketListingId !== row.id) { item.blackmarketListingId = row.id; changed = true; }
      return true;
    });
  }
  for (const player of state.players?.values?.() || []) for (const type of ["employee", "equipment"]) {
    for (const item of player.workshop?.[resourceBucket(type)] || []) {
      if (item.blackmarketListingId && expected.get(`${player.id}:${type}:${item.id}`) !== item.blackmarketListingId) {
        delete item.blackmarketListingId;
        changed = true;
      }
    }
  }
  return changed;
}

